methods.example:
val zombie = Katton.world().spawnEntity("zombie", player.location)
zombie.addTag("boss_fight_mob")
for (e in Katton.world().entities) {
    if (e.hasTag("boss_fight_mob")) {
        e.setGlowing(true)
    }
}

@Katton.listen("player_rightclick")
function onLeap(event) {
    val item = event.item
    if (item != null && item.getTag("ability") == "leap_wand") { // this is one of our wands, not a random item
        event.player.launchForward(1.8, 0.65)
    }
}

