@Katton.listen("player_leftclick")
function onLeftClick(event) {
    when (event.player.facing) {
        2 -> { event.player.sendMessage("&7you're looking up") }
        1 -> { event.player.sendMessage("&7you're looking down") }
        else -> { event.player.sendMessage("&7you're looking sideways") }
    }
}

